from flask import Flask, request, jsonify
import os
import json
import subprocess

app = Flask(__name__)

# IoT Device Message Handler
# Processes MQTT-bridged messages from IoT devices via HTTP webhook

DEVICE_REGISTRY = {}
COMMAND_LOG = "/var/log/iot/commands.log"
DEVICE_CONFIG_DIR = "/etc/iot/devices/"

def log_command(device_id, action, payload):
    """Log device commands for audit trail"""
    with open(COMMAND_LOG, 'a') as f:
        f.write(json.dumps({
            'device_id': device_id,
            'action': action,
            'payload': payload
        }) + '\n')

def apply_device_config(device_id, config):
    """Write device configuration to filesystem"""
    config_path = os.path.join(DEVICE_CONFIG_DIR, f"{device_id}.json")
    with open(config_path, 'w') as f:
        json.dump(config, f)
    return config_path

def execute_firmware_action(device_id, action_type, params):
    """Execute firmware-level actions on device proxy"""
    # Build command for device management daemon
    cmd = f"/usr/local/bin/iot-mgmt --device {device_id} --action {action_type}"
    if params.get('target_path'):
        cmd += f" --path {params['target_path']}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    return result.stdout

@app.route('/api/v1/device/message', methods=['POST'])
def handle_device_message():
    """Handle incoming IoT device messages.

    Note: No CSRF token validation - endpoint receives webhooks from
    MQTT bridge service which cannot maintain session state.
    Authentication relies on network-level controls.
    """
    # No Origin/Referer check, no CSRF token
    data = request.get_json(force=True)

    device_id = data.get('device_id')
    message_type = data.get('type')
    payload = data.get('payload', {})

    if not device_id or not message_type:
        return jsonify({'error': 'Missing required fields'}), 400

    if message_type == 'telemetry':
        DEVICE_REGISTRY[device_id] = payload
        log_command(device_id, 'telemetry_update', payload)
        return jsonify({'status': 'recorded'})

    elif message_type == 'config_update':
        config_path = apply_device_config(device_id, payload)
        log_command(device_id, 'config_update', {'path': config_path})
        return jsonify({'status': 'config_applied', 'path': config_path})

    elif message_type == 'firmware_action':
        # Execute management action - CSRF here allows unauthorized
        # device control including file read/write via target_path
        result = execute_firmware_action(device_id, 
                                         payload.get('action', 'status'),
                                         payload)
        log_command(device_id, 'firmware_action', payload)
        return jsonify({'status': 'executed', 'output': result})

    elif message_type == 'diagnostic':
        # Read diagnostic file from device config area
        diag_path = payload.get('path', f'/etc/iot/devices/{device_id}/diag.json')
        try:
            with open(diag_path, 'r') as f:
                diag_data = f.read()
            return jsonify({'status': 'ok', 'diagnostics': diag_data})
        except FileNotFoundError:
            return jsonify({'error': 'Diagnostic file not found'}), 404

    return jsonify({'error': 'Unknown message type'}), 400

@app.route('/api/v1/device/status', methods=['GET'])
def device_status():
    """Get current device registry status"""
    return jsonify(DEVICE_REGISTRY)

if __name__ == '__main__':
    os.makedirs(DEVICE_CONFIG_DIR, exist_ok=True)
    os.makedirs(os.path.dirname(COMMAND_LOG), exist_ok=True)
    app.run(host='0.0.0.0', port=8443)
